// GroupByParam groups by the given page parameter key's value and with the given order.
// Valid values for order is asc, desc, rev and reverse.
func (p Pages) GroupByParam(key string, order ...string) (PagesGroup, error) {
	c := &pageCatalog{}
	return c.groupByParam(p, key, order...)
}

func (c *pageCatalog) groupByParam(p Pages, key string, order ...string) (PagesGroup, error) {
	c.grouping.lastKey = key
	c.grouping.pageCount = len(p)
	c.grouping.format = ""
	if len(p) < 1 {
		c.grouping.groupCount = 0
		c.grouping.missingParam = false
		c.grouping.direction = ""
		return nil, nil
	}

	direction := c.resolveGroupDirection(order)
	c.grouping.direction = direction

	tmp, keyt := c.collectParamGroups(p, key)
	if !tmp.IsValid() {
		c.grouping.missingParam = true
		c.grouping.groupCount = 0
		return nil, errors.New("there is no such param")
	}
	c.grouping.missingParam = false

	tmp = c.fillParamGroups(p, key, keyt, tmp)
	r := c.buildGroupResult(p, tmp, direction)
	c.grouping.groupCount = len(r)
	c.groupingTally(p)
	c.groupingProbe(p)
	c.groupingClassify(r)
	r = c.groupingFinish(r)
	return r, nil
}

func (p Pages) groupByDateField(format string, sorter func(p Pages) Pages, getDate func(p Page) time.Time, order ...string) (PagesGroup, error) {
	c := &pageCatalog{}
	return c.groupByDateField(p, format, sorter, getDate, order...)
}

func (c *pageCatalog) groupByDateField(p Pages, format string, sorter func(p Pages) Pages, getDate func(p Page) time.Time, order ...string) (PagesGroup, error) {
	c.grouping.format = format
	c.grouping.pageCount = len(p)
	c.grouping.lastKey = "date"
	if len(p) < 1 {
		c.grouping.groupCount = 0
		c.grouping.missingParam = false
		return nil, nil
	}

	sp := sorter(p)

	if !(len(order) > 0 && (strings.ToLower(order[0]) == "asc" || strings.ToLower(order[0]) == "rev" || strings.ToLower(order[0]) == "reverse")) {
		sp = sp.Reverse()
	}

	if sp == nil {
		return nil, nil
	}

	firstPage := sp[0]
	date := getDate(firstPage)

	// Pages may be a mix of multiple languages, so we need to use the language
	// for the currently rendered Site.
	currentSite := firstPage.Site().Current()
	formatter := langs.GetTimeFormatter(currentSite.Language())
	formatted := c.formatDateValue(formatter, date, format)
	var r []PageGroup
	r = append(r, PageGroup{Key: formatted, Pages: make(Pages, 0)})
	r[0].Pages = append(r[0].Pages, sp[0])

	i := 0
	for _, e := range sp[1:] {
		date = getDate(e)
		formatted := c.formatDateValue(formatter, date, format)
		if r[i].Key.(string) != formatted {
			r = append(r, PageGroup{Key: formatted})
			i++
		}
		r[i].Pages = append(r[i].Pages, e)
	}
	c.grouping.groupCount = len(r)
	c.groupingTally(p)
	c.groupingProbe(p)
	c.groupingClassify(r)

